$ErrorActionPreference='Stop'
function Need($ok,[string]$why){if(!$ok){throw $why}}
function Sha([byte[]]$body){$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($body))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function AtomicWrite([string]$path,[byte[]]$body){$tmp=$path+'.new-'+[guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$body);Move-Item -LiteralPath $tmp -Destination $path -Force}finally{if(Test-Path -LiteralPath $tmp){Remove-Item -LiteralPath $tmp -Force}}}
$root='F:\CABAL_291_TEST'
Need ($env:OS -eq 'Windows_NT' -and [Environment]::Is64BitProcess) 'WINDOWS_X64_POWERSHELL_REQUIRED'
Need (!(Get-Process -Name CabalMain -ErrorAction SilentlyContinue)) 'AIZVER_SPELI_PIRMS_LABOJUMA'
Need ((Get-FileHash -LiteralPath "$root\Bin\x64\CabalMain.exe" -Algorithm SHA256).Hash -eq '52e7956d4781fea1f0369cac8ab1eac4c3ddec2d1977c6557be53ec2b79885d9') 'CLIENT291_BUILD_DIFFERS'
$own=Join-Path $root '.ep36-runtime'
Need (Test-Path -LiteralPath $own -PathType Container) 'PASTAVIGA_START_BAT_PROFILS_NAV_ATRASTS'
Need (!((Get-Item -Force -LiteralPath $own).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'RUNTIME_REPARSE_REFUSED'
$activePath=Join-Path $own 'active.json'
Need (!((Get-Item -Force -LiteralPath $activePath).Attributes -band ([IO.FileAttributes]::ReparsePoint -bor [IO.FileAttributes]::ReadOnly))) 'ACTIVE_PROFILE_NOT_WRITABLE'
$before=[IO.File]::ReadAllBytes($activePath)
$active=[Text.Encoding]::UTF8.GetString($before) | ConvertFrom-Json
Need ($active.Profile -match '^profile-[a-f0-9-]+$') 'RUNTIME_PROFILE_PATH_INVALID'
$oldProfile=Join-Path $own $active.Profile
Need (!((Get-Item -Force -LiteralPath $oldProfile).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'PROFILE_REPARSE_REFUSED'
foreach($p in $active.Files.PSObject.Properties){
 Need ($p.Name -match '^[A-Za-z0-9_.-]+$') 'PROFILE_MEMBER_NAME_INVALID'
 $path=Join-Path $oldProfile $p.Name
 Need (!((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'PROFILE_MEMBER_REPARSE_REFUSED'
 Need ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -eq $p.Value) ('RUNTIME_FILE_CHANGED_'+$p.Name)
}
$current=(Get-FileHash -LiteralPath (Join-Path $oldProfile 'Client291-Runtime.cs') -Algorithm SHA256).Hash.ToLowerInvariant()
if($current -eq 'b79cbcf427ee794c3e3c052cd2f4ca3b065af4099e2d3b2284d9ca9974470839'){'GEMS_FIX_JAU_AKTIVS; PALAID_F_CABAL_291_TEST_START_BAT';return}
Need ($current -eq '67efc35781d513a0a068ab8339538cc405bf35a4e6c75708c020cb28da17e240') 'NEATPAZITS_PASREIZEJAIS_RUNTIME; NEKAS_NAV_MAINITS'
$launcher=Join-Path $oldProfile 'Launcher.exe'
Need (!((Get-Item -Force -LiteralPath $launcher).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'LAUNCHER_REPARSE_REFUSED'
Need ((Get-FileHash -LiteralPath $launcher -Algorithm SHA256).Hash -eq $active.LauncherSHA) 'OWN_LAUNCHER_CHANGED'
$source=[Convert]::FromBase64String('')
Need ((Sha $source) -eq 'b79cbcf427ee794c3e3c052cd2f4ca3b065af4099e2d3b2284d9ca9974470839') 'GEMS_RUNTIME_PAYLOAD_DIFFERS'
$name='profile-b79cbcf427ee-'+[guid]::NewGuid().ToString('N').Substring(0,8)
$profile=Join-Path $own $name
[void][IO.Directory]::CreateDirectory($profile)
foreach($p in $active.Files.PSObject.Properties){[IO.File]::Copy((Join-Path $oldProfile $p.Name),(Join-Path $profile $p.Name))}
[IO.File]::Copy($launcher,(Join-Path $profile 'Launcher.exe'))
[IO.File]::WriteAllBytes((Join-Path $profile 'Client291-Runtime.cs'),$source)
$compiler=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
Need (Test-Path -LiteralPath $compiler -PathType Leaf) 'WINDOWS_FRAMEWORK_COMPILER_MISSING'
'PARBAUDU_GEMS_LABOJUMA_KOMPILACIJU...'
& $compiler /nologo /target:library /platform:x64 /optimize+ ("/out:"+(Join-Path $profile 'Runtime-CompileCheck.dll')) (Join-Path $profile 'Client291-Runtime.cs')
Need ($LASTEXITCODE -eq 0) 'GEMS_RUNTIME_BUILD_FAILED; VECAS_PALAISANAS_PROFILS_SAGLABATS'
$active.Files.'Client291-Runtime.cs'='b79cbcf427ee794c3e3c052cd2f4ca3b065af4099e2d3b2284d9ca9974470839'
$hashes=[ordered]@{}
foreach($p in $active.Files.PSObject.Properties){Need ((Get-FileHash -LiteralPath (Join-Path $profile $p.Name) -Algorithm SHA256).Hash -eq $p.Value) ('NEW_RUNTIME_FILE_DIFFERS_'+$p.Name);$hashes[$p.Name]=$p.Value}
[IO.File]::WriteAllText((Join-Path $profile 'hashes.json'),($hashes|ConvertTo-Json),[Text.Encoding]::ASCII)
Need ((Get-FileHash -LiteralPath (Join-Path $profile 'Launcher.exe') -Algorithm SHA256).Hash -eq $active.LauncherSHA) 'NEW_LAUNCHER_COPY_DIFFERS'
$backup=Join-Path ([Environment]::GetFolderPath('MyDocuments')) ('CABAL291-Launcher-Backups\gems-'+[guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($backup)
[IO.File]::WriteAllBytes((Join-Path $backup 'active.json'),$before)
$active.Profile=$name
$active|Add-Member -NotePropertyName CashShopGemsPreview -NotePropertyValue 'first-existing-model-128' -Force
$after=[Text.Encoding]::UTF8.GetBytes(($active|ConvertTo-Json -Depth 8))
Need ((Sha ([IO.File]::ReadAllBytes($activePath))) -eq (Sha $before)) 'ACTIVE_PROFILE_CHANGED_DURING_BUILD'
try{AtomicWrite $activePath $after;Need ((Sha ([IO.File]::ReadAllBytes($activePath))) -eq (Sha $after)) 'NEW_ACTIVE_PROFILE_READBACK_DIFFERS'}catch{AtomicWrite $activePath $before;throw}
'GEMS_FIX_UZSTADITS; PALAID_F_CABAL_291_TEST_START_BAT'
'REZERVES_KOPIJA='+$backup
